```c
/*
 * Tree files support
 *
 * A treefiles export stores its data in a tree of small block files
 * rather than in one large file. This is useful on filesystems that
 * do not handle large files well (ftpfs, davfs, other network
 * filesystems).
 *
 * The export is divided into blocks of TREEPAGESIZE bytes. Each block
 * lives in its own file, and the files are spread over a tree of
 * directories rooted at the export name, with at most TREEDIRSIZE
 * entries per directory. A block's position in the tree is derived
 * from its block number: written in base TREEDIRSIZE, the digits name
 * the directories (top level first) and the block file.
 *
 * Missing blocks read back as all zeros, so blocks that were never
 * written (or that were trimmed) don't need to take up space.
 */

#include "lfs.h"
#include "nbd-debug.h"

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "treefiles.h"

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Append to name the path of the block file holding position pos.
 *
 * name must contain the root of the tree (i.e. the export name) on
 * entry. On successful return, it holds the full path of the block
 * file.
 *
 * @param name root of the tree on entry, full path on return
 * @param lenmax size of the name buffer
 * @param size total size of the export
 * @param pos position within the export to find the block for
 * @param ppos out: position of pos within the block file
 */
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t nr;
	off_t cnt;
	off_t div;
	char *c;
	int len;
	int w;

	assert(pos >= 0);
	assert(size > 0);
	assert(pos < size);

	nr = pos / TREEPAGESIZE;
	*ppos = pos % TREEPAGESIZE;

	/*
	 * Find out how many levels of directories we need: one extra
	 * level every time the number of blocks left to store exceeds
	 * TREEDIRSIZE. div is TREEDIRSIZE to the power of that number
	 * of levels.
	 */
	cnt = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	div = 1;
	while (cnt > TREEDIRSIZE) {
		cnt = (cnt + TREEDIRSIZE - 1) / TREEDIRSIZE;
		div *= TREEDIRSIZE;
	}

	c = name + strlen(name);
	len = lenmax - (c - name);
	while (div > 0) {
		w = snprintf(c, len, "/%04X", (unsigned int)((nr / div) % TREEDIRSIZE));
		if (w < 0 || w >= len) {
			DEBUG("treefiles: path too long for buffer\n");
			exit(EXIT_FAILURE);
		}
		c += w;
		len -= w;
		div /= TREEDIRSIZE;
	}
}
```

