```c
/**
 * Open the block file holding position pos of a treefiles export,
 * creating the directories (and, for a writable open, the file) as
 * needed.
 *
 * @param name root of the tree (export name)
 * @param mode open(2) flags; O_RDONLY for reads, anything else for
 * writes
 * @param size total size of the export
 * @param pos position within the export
 * @param mutex serializes directory creation between threads
 * @return a file descriptor on success, -1 on error (errno is set)
 */
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	off_t ppos;
	char *sep;
	int fd;

	if (snprintf(path, sizeof(path), "%s", name) >= (int)sizeof(path)) {
		errno = ENAMETOOLONG;
		return -1;
	}
	construct_path(path, sizeof(path), size, pos, &ppos);

	if ((mode & O_ACCMODE) != O_RDONLY) {
		sep = strrchr(path, '/');
		*sep = '\0';
		pthread_mutex_lock(mutex);
		mkdir_path(path);
		pthread_mutex_unlock(mutex);
		*sep = '/';
		mode |= O_CREAT;
	}

	fd = open(path, mode, 0600);
	DEBUG("treefiles: open %s: fd %d\n", path, fd);
	return fd;
}
