/*
 * Tree files support
 *
 * An export flagged with treefiles is not backed by a single large
 * file. Instead, the exported block device is split into fixed-size
 * blocks of TREEPAGESIZE bytes, and every block is stored in its own
 * file. These block files are organised in a tree of directories with
 * at most TREEDIRSIZE entries per directory, so that the export can be
 * served from filesystems that do not cope well with large files.
 *
 * The position of a block in the tree is derived from its block
 * number: written as a base-TREEDIRSIZE number, each digit names one
 * level of the tree, most significant digit first, with the least
 * significant digit naming the block file itself. Blocks that are
 * never written simply have no file; reading them returns zeroes.
 */

/* Includes LFS defines, which defines behaviours of some of the
 * following headers, so must come before those */
#include "lfs.h"
#include "config.h"
#include "nbd-debug.h"

#include <assert.h>
#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "treefiles.h"

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * Compute the number of directory levels required to store the blocks of
 * an export of the given size, given that every directory may hold at
 * most TREEDIRSIZE entries.
 *
 * @param size the total size of the export
 * @return the number of directory levels below the root (0 if all
 * block files fit in the root directory itself)
 **/
static int tree_depth(off_t size) {
	off_t nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	off_t cap = TREEDIRSIZE;
	int depth = 0;

	while(nblocks > cap) {
		/* don't overflow cap for absurdly large exports; the
		 * number of blocks itself is bounded by size */
		if(cap > nblocks / TREEDIRSIZE)
			break;
		cap *= TREEDIRSIZE;
		depth++;
	}
	return depth;
}

/**
 * Construct the path of the block file that holds the data at a given
 * position of a treefiles export.
 *
 * The path is appended to ``name``, which on entry must contain the
 * root of the tree (i.e., the export name).
 *
 * @param name on entry the root of the tree, on exit the full path of
 * the block file
 * @param lenmax the total size of the buffer ``name`` points at
 * @param size the total size of the export
 * @param pos the position within the export we want the path for
 * @param ppos out: the position of ``pos`` within the block file
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t blk;
	int depth;
	int used;
	off_t div;
	int i;
	char *c;

	assert(name != NULL);
	assert(pos >= 0);
	assert(size > 0);
	assert(pos < size);

	blk = pos / TREEPAGESIZE;
	if(ppos)
		*ppos = pos % TREEPAGESIZE;

	depth = tree_depth(size);

	/* div = TREEDIRSIZE^depth, i.e. the weight of the most
	 * significant digit of the block number */
	div = 1;
	for(i = 0; i < depth; i++)
		div *= TREEDIRSIZE;

	used = strlen(name);
	c = name + used;
	for(i = depth; i >= 0; i--) {
		int w;
		off_t digit = (blk / div) % TREEDIRSIZE;

		w = snprintf(c, lenmax - used, "/%04X", (unsigned int)digit);
		if(w < 0 || w >= lenmax - used) {
			/* truncate rather than overflow; the caller's
			 * buffer is expected to be large enough */
			name[lenmax - 1] = '\0';
			return;
		}
		c += w;
		used += w;
		div /= TREEDIRSIZE;
	}
}

/**
 * Recursively create a directory and any missing parents, like
 * ``mkdir -p``. Existing directories are not an error.
 *
 * @param path the directory to create. The string is temporarily
 * modified while the parents are created, but restored before return.
 **/
void mkdir_path(char *path) {
	char *sep;

	sep = path;
	while((sep = strchr(sep + 1, '/')) != NULL) {
		*sep = '\0';
		if(mkdir(path, 0700) < 0 && errno != EEXIST)
			DEBUG("treefiles: could not create directory %s: %s", path, strerror(errno));
		*sep = '/';
	}
	if(mkdir(path, 0700) < 0 && errno != EEXIST)
		DEBUG("treefiles: could not create directory %s: %s", path, strerror(errno));
}

/**
 * Open the block file that holds the data at a given position of a
 * treefiles export, creating the directories leading up to it as
 * needed.
 *
 * @param name the root of the tree (i.e., the export name)
 * @param mode the open(2) mode. Anything other than O_RDONLY causes
 * the file (and the directories leading up to it) to be created if
 * they do not exist yet.
 * @param size the total size of the export
 * @param pos the position within the export we want the block file for
 * @param mutex a mutex used to serialise directory creation between
 * the worker threads
 * @return a file descriptor for the block file on success, or -1 on
 * error, with errno set appropriately
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	char dir[PATH_MAX];
	char *sep;
	int fd;
	int create = ((mode & O_ACCMODE) != O_RDONLY);

	construct_path(path, sizeof(path), size, pos, NULL);

	if(create) {
		/* create the directories leading up to the file */
		if(snprintf(dir, sizeof(dir), "%s", path) >= (int)sizeof(dir)) {
			errno = ENAMETOOLONG;
			return -1;
		}
		sep = strrchr(dir, '/');
		if(sep != NULL) {
			*sep = '\0';
			pthread_mutex_lock(mutex);
			mkdir_path(dir);
			pthread_mutex_unlock(mutex);
		}
		mode |= O_CREAT;
	}

	DEBUG("treefiles: open %s\n", path);
	fd = open(path, mode, 0600);

	return fd;
}

/**
 * Remove the block file that holds the data at a given position of a
 * treefiles export, if it exists. Used to give the space back to the
 * filesystem when a block is marked as unused.
 *
 * @param name the root of the tree (i.e., the export name)
 * @param size the total size of the export
 * @param pos the position within the export we want to remove the
 * block file for
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];

	construct_path(path, sizeof(path), size, pos, NULL);
	if(unlink(path) < 0 && errno != ENOENT)
		DEBUG("treefiles: could not remove %s: %s", path, strerror(errno));
}

