 * an export of the given size, given that every directory may hold at
 * most TREEDIRSIZE entries.
 *
 * @param size the total size of the export
 * @return the number of directory levels below the root (0 if all
 * block files fit in the root directory itself)
 **/
static int tree_depth(off_t size) {
	off_t nblocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	off_t cap = TREEDIRSIZE;
	int depth = 0;

	while(nblocks > cap) {
		/* don't overflow cap for absurdly large exports; the
		 * number of blocks itself is bounded by size */
		if(cap > nblocks / TREEDIRSIZE)
			break;
		cap *= TREEDIRSIZE;
		depth++;
	}
	return depth;
}

