/**
 * Sync a directory and, recursively, everything below it. Used to
 * implement FLUSH for treefiles exports: block files are opened and
 * closed on demand, so flushing means walking the tree and fsync()ing
 * every block file and directory in it.
 *
 * @param dirpath the directory to sync
 * @return 0 on success, -1 on error
 **/
static int sync_tree(const char *dirpath) {
	DIR *d;
	struct dirent *de;
	char path[PATH_MAX];
	int ret = 0;
	int dfd;

	d = opendir(dirpath);
	if(d == NULL) {
