			ret = -1;
			continue;
		}
		if(S_ISDIR(st.st_mode)) {
			if(sync_tree(path) < 0)
				ret = -1;
		} else if(S_ISREG(st.st_mode)) {
			int fd = open(path, O_RDONLY);

			if(fd >= 0) {
				if(fsync(fd) < 0)
					ret = -1;
				close(fd);
			} else {
				ret = -1;
			}
		}
	}
	closedir(d);

	dfd = open(dirpath, O_RDONLY);
	if(dfd >= 0) {
		if(fsync(dfd) < 0)
			ret = -1;
		close(dfd);
	} else {
		ret = -1;
	}
	return ret;
}

/**
 * Sync all block files and directories of a treefiles export.
 *
 * @param name the root of the tree (i.e., the export name)
 * @return 0 on success, -1 on error
 **/
int treefiles_sync(char *name) {
	return sync_tree(name);
}

