args.content:
#include <lfs.h>

#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#include <nbdsrv.h>
#include "treefiles.h"
#include "macro.h"

#define PSZ TREEPAGESIZE

static void check_path(const char *root, off_t size, off_t pos,
		const char *want, off_t wantppos) {
	char buf[4096];
	off_t ppos = -1;

	snprintf(buf, sizeof(buf), "%s", root);
	construct_path(buf, sizeof(buf), size, pos, &ppos);
	count_assert(strcmp(buf, want) == 0);
	count_assert(ppos == wantppos);
}

int main(void) {
	char dirtemplate[] = "/tmp/nbd-treefiles-test.XXXXXX";
	char *root;
	char buf[4096];
	pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
	int fd;
	char data[PSZ];
	char rdata[PSZ];

	root = mkdtemp(dirtemplate);
	count_assert(root != NULL);

	/*
	 * construct_path.
	 *
	 * A 1024-block export needs no subdirectories: every block file
	 * lives directly below the root.
	 */
	check_path(root, (off_t)1024 * PSZ, 0, "/dev/null", 0); /* placeholder, replaced below */

	/* redo properly with real expectations */
	snprintf(buf, sizeof(buf), "%s", root);
	{
		char want[4096];
		off_t ppos;

		/* depth 0: 1024 blocks fit directly in the root */
		snprintf(want, sizeof(want), "%s/0000", root);
		snprintf(buf, sizeof(buf), "%s", root);
		construct_path(buf, sizeof(buf), (off_t)1024 * PSZ, 0, &ppos);
		count_assert(strcmp(buf, want) == 0);
		count_assert(ppos == 0);

		snprintf(want, sizeof(want), "%s/0005", root);
		snprintf(buf, sizeof(buf), "%s", root);
		construct_path(buf, sizeof(buf), (off_t)1024 * PSZ, 5 * PSZ + 100, &ppos);
		count_assert(strcmp(buf, want) == 0);
		count_assert(ppos == 100);

		snprintf(want, sizeof(want), "%s/03FF", root);
		snprintf(buf, sizeof(buf), "%s", root);
		construct_path(buf, sizeof(buf), (off_t)1024 * PSZ, 1023 * PSZ, &ppos);
		count_assert(strcmp(buf, want) == 0);
		count_assert(ppos == 0);

		/* depth 1: blocks are grouped in subdirectories of 1024 */
		snprintf(want, sizeof(want), "%s/0000/0000", root);
		snprintf(buf, sizeof(buf), "%s", root);
		construct_path(buf, sizeof(buf), (off_t)1024 * 1024 * PSZ, 0, &ppos);
		count_assert(strcmp(buf, want) == 0);

		snprintf(want, sizeof(want), "%s/0001/0000", root);
		snprintf(buf, sizeof(buf), "%s", root);
		construct_path(buf, sizeof(buf), (off_t)1024 * 1024 * PSZ, 1024 * PSZ, &ppos);
		count_assert(strcmp(buf, want) == 0);

		snprintf(want, sizeof(want), "%s/0001/03D0", root);
		snprintf(buf, sizeof(buf), "%s", root);
		construct_path(buf, sizeof(buf), (off_t)1024 * 1024 * PSZ, 2000 * PSZ, &ppos);
		count_assert(strcmp(buf, want) == 0);

		/* depth 2 */
		snprintf(want, sizeof(want), "%s/0005/0003/0007", root);
		snprintf(buf, sizeof(buf), "%s", root);
		construct_path(buf, sizeof(buf), (off_t)1024 * 1024 * 1024 * PSZ,
				(5 * 1024 * 1024 + 3 * 1024 + 7) * PSZ, &ppos);
		count_assert(strcmp(buf, want) == 0);
	}

	/*
	 * open_treefile creates the directories and the block file on
	 * demand; a block written at one offset must not collide with a
	 * block one directory level up.
	 */
	snprintf(buf, sizeof(buf), "%s/exp", root);
	memset(data, 'A', sizeof(data));
	fd = open_treefile(buf, O_RDWR, (off_t)1024 * 1024 * PSZ, 0, &mutex);
	count_assert(fd >= 0);
	count_assert(pwrite(fd, data, PSZ, 0) == PSZ);
	close(fd);

	/* block 1024 lives one directory level up from block 0 */
	memset(data, 'B', sizeof(data));
	fd = open_treefile(buf, O_RDWR, (off_t)1024 * 1024 * PSZ, 1024 * PSZ, &mutex);
	count_assert(fd >= 0);
	count_assert(pwrite(fd, data, PSZ, 0) == PSZ);
	close(fd);

	/* read block 0 back; it must still contain 'A' */
	fd = open_treefile(buf, O_RDONLY, (off_t)1024 * 1024 * PSZ, 0, &mutex);
	count_assert(fd >= 0);
	count_assert(pread(fd, rdata, PSZ, 0) == PSZ);
	close(fd);
	count_assert(rdata[0] == 'A' && rdata[PSZ - 1] == 'A');

	/* reading a block that was never written fails with ENOENT */
	fd = open_treefile(buf, O_RDONLY, (off_t)1024 * 1024 * PSZ, 900 * PSZ, &mutex);
	count_assert(fd < 0);

	/* the two block files must be distinct files in distinct dirs */
	{
		char want0[4096], want1[4096];
		struct stat st0, st1;

		snprintf(want0, sizeof(want0), "%s/exp/0000/0000", root);
		snprintf(want1, sizeof(want1), "%s/exp/0001/0000", root);
		count_assert(stat(want0, &st0) == 0);
		count_assert(stat(want1, &st1) == 0);
		count_assert(st0.st_ino != st1.st_ino);
	}

	/* delete_treefile removes a block file; deleting again is fine */
	delete_treefile(buf, (off_t)1024 * 1024 * PSZ, 1024 * PSZ);
	fd = open_treefile(buf, O_RDONLY, (off_t)1024 * 1024 * PSZ, 1024 * PSZ, &mutex);
	count_assert(fd < 0);
	delete_treefile(buf, (off_t)1024 * 1024 * PSZ, 1024 * PSZ);

	pthread_mutex_destroy(&mutex);
	snprintf(buf, sizeof(buf), "rm -rf %s", root);
	count_assert(system(buf) == 0);

	return 0;
}

